// Printed-mushaf position (Madinah Mushaf 1441H, 15 lines per page) of every Juz 30 verse.
// Generated by scripts/build-verse-locations.py into verseLocations.json.

import locations from "@/features/quran/data/verseLocations.json";

export interface VerseLocation {
  /** Page where the verse starts. */
  page: number;
  /** Printed line (1-15) of that page where the verse starts. */
  line: number;
  endPage: number;
  endLine: number;
}

type RawLocation = readonly [number, number, number, number];

const RAW = locations as unknown as Readonly<
  Record<string, readonly RawLocation[]>
>;

export const LINES_PER_PAGE = 15;

let pageRange: { min: number; max: number } | undefined;

/** Lowest and highest page that holds any verse of the app (582-604 for Juz 30). */
export function pageBounds(): { min: number; max: number } {
  if (!pageRange) {
    let min = Number.POSITIVE_INFINITY;
    let max = Number.NEGATIVE_INFINITY;

    Object.values(RAW).forEach((rows) =>
      rows.forEach(([page, , endPage]) => {
        min = Math.min(min, page);
        max = Math.max(max, endPage);
      }),
    );
    pageRange = { min, max };
  }

  return pageRange;
}

export function verseLocation(
  surahId: number,
  ayah: number,
): VerseLocation | undefined {
  const row = RAW[String(surahId)]?.[ayah - 1];

  if (!row) {
    return undefined;
  }

  return { page: row[0], line: row[1], endPage: row[2], endLine: row[3] };
}
